/** Machine translated draft; religious and linguistic review pending. */
internal object DuaDoiDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_travel_full" to DuaText("पूरी जातरा दी विनती", "ऐ अल्लाह, इस जातरा च हम तुंʼदे शा धर्म ते धर्मपरायणता ते तुंʼदे मन गी खुश करने आह्ले कम्में आस्तै मंगदे न। ऐ अल्लाह, इस जातरा गी साडे आस्तै सौखा बनाओ ते एह्दे बिच्च दी दूरी गी घट्ट करो। ऐ अल्लाह, तुस जातरा च साथी ते परोआर दे संरक्षक ओ।", "जिसलै कुसै जातरा पर निकलदे होई,'सुभानल्लधी सखारा'दे परैंत्त।", "पूरा सुन्नत दुआ दी यात्रा करदा ऐ।"),
        "dua_return_travel" to DuaText("यात्रा थमां बापसी", "असीं बापस आ \"रदे आं, पश्चाताप करदे आं, अपने प्रभु दी पूजा ते स्तुति करदे आं।", "इक जातरा थमां बापस औने पर।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् इक जातरा थमां बापस औने पर आखेआ हा।"),
        "dua_farewell_traveller" to DuaText("इक यात्री गी विदाई दी बोली", "में तुंʼदा धर्म, भरोसा ते तुंʼदे कर्में दा नतीजा अल्लाह गी सुपुर्द करदा आं।", "जिसलै कुसै यात्री गी विदाई दित्ती जंदी ऐ।", "जो चीज अल्लाह गी सौंपी गेई ऐ, ओह् कदें नेईं गुजरी जंदी।"),
        "dua_entering_town" to DuaText("इक थाह्र पर रुकना", "में अल्लाह दे सारे सृजनें दी बुराई शा उंʼदे सिद्ध वचनें च शरण लैंदा आं।", "जिसलै कुसै थाह्र पर रुको जां कुसै नमें शैह्र च औने पर।", "जिसलै तक्कर ओह् ओह्दे शा नेईं निकली जंदा, उसलै तक्कर किश बी नुकसान नेईं होग।"),
        "dua_boarding_ship" to DuaText("इक जहाज़/वाहन च चढ़ना", "अल्लाह दे नांऽ पर ऐ एह् नौकायन ते एह् लंगर। मेरा रब बड़ा क्षमाशील, दयावान ऐ।", "जिसलै कुसै पोत जां वाहन च चढ़दे ओ-पैगंबर नूह (अ. स.) दे शब्द।", "इक कुरान दी आयत-नूह (ए. ऐस्स.) दे सन्दूक दी दुआ।"),
        "dua_istighfar_hayyul_qayyum" to DuaText("हयुल-कयूम दे कन्नै इस्तिघफर", "में अल्लाह शा माफ़ी मंगदा आं, जेह्दे अलावा कोई पूज्य-प्रभु, सदाबहार, पालन-पोषण करने आह्ला नेईं ऐ, ते में पश्चाताप च ओह्दे बक्खी रुख करदा आं।", "पश्चाताप आस्तै।", "उंʼदे पाप माफ करी दित्ता जंदा ऐ, भले गै ओह् जुद्ध दे मैदान थमां नस्सी गेआ हा।"),
        "dua_rabbighfir_warham" to DuaText("रब्बीघफिर वारहम", "हे मेरे प्रभु, माफ करो ते दया करो, तुस दया करने आह्ले लोकें च सभनें शा शैल ओ।", "इक कुरानिक दुआ-माफी ते दया आस्तै।", "सूरह अल-मु'मिनुन दी खीरली आयत।"),
        "dua_majlis_kaffarah" to DuaText("कफ़रात अल-मजलिस", "महिमावान ऐ, हे अल्लाह, ते स्तुति तुंʼदी ऐ। में गवाही दिंदा आं जे तुंʼदे अलावा कोई पूज्य-प्रभु नेईं ऐ। में तेरी क्षमा मंगदा आं ते तुंʼदे बक्खी पश्चाताप च मुड़दा आं।", "जिसलै इक सभा थमां उठी जाई।", "एह् सभा च जेह्ड़ा बी गलत आखेआ गेआ हा, ओह्दे आस्तै इक माफी बनी जंदी ऐ।"),
        "dua_jami_forgiveness" to DuaText("व्यापक माफी", "हे अल्लाह, मेरी गलतियें, मेरी अज्ञानता, मेरे मामलें च मेरी अतिआत्मकता ते ओह् सभनें चीजें गी माफ करी देओ जेह्ड़े तुस मुझसे मते चंगे कन्नै जानदे ओ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम दी इक व्यापक दुआ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम इस दुआ गी त्यार करदे हे।"),
        "dua_parents_nuh" to DuaText("माता-पिता आस्तै नूंह (ए. ऐस्स.) दी दुआ", "ऐ मेरे रब, जे कोई मेरे घर च विश्वासी दे रूपा च दाखल होंदा ऐ, ते सारे विश्वासी मर्द ते मुश्ताकियां महिलाएं गी माफ करी देओ।", "अपने माता-पिता ते विश्वासी लोकें आस्तै।", "पैगंबर नूंह (अ. स.) दी दुआ।"),
        "dua_shukr_parents" to DuaText("माता-पिता ते धर्मी संतानें आस्तै आभार", "ऐ मेरे रब, तुंʼदी ते मेरे माता-पिता पर होई दी कृपा आस्तै, ते तुसें गी खुश करने आह्ले नेक कम्म करने आस्तै, ते अपनी संतानें गी धर्मी बनाने आस्तै, मैं तुंʼदी बक्खी पश्चाताप च वापस जाई सकनां ते में बी उंʼदे बख्शीशें च आं।", "चालीएं बʼरें दी उमरी तक्कर पुज्जे दा कुरान दा दुआ।", "कृतज्ञता, भले कम्म ते अपने ञ्याणें दी धार्मिकता-एह् सभनें गी इक दुआ च।"),
        "dua_intimacy" to DuaText("वैवाहिक संबंधें शा पैह्लें", "अल्लाह दे नांऽ पर। ऐ अल्लाह, शयतान गी असां शा दूर र'वो ते शयतान गी तुस सानू जेह्ड़ा (ञ्याणे) दिंदे ओ ओह्दे शा दूर र'वो।", "वैवाहिक संबंधें शा पैह्लें।", "जे इक ञ्याणे गी फैसला दित्ता जंदा ऐ, तां शैतन इसगी कदें बी नुकसान नेईं पहुँचाएगा।"),
        "dua_ibrahim_children_protection" to DuaText("घर ते ञ्याणें दी सुरक्षा", "मेरे भगवान, इस शैह्र गी सुरक्खत करो ते मिगी ते मेरे ञ्याणें गी मूर्तियें दी पूजा शा दूर र'व।", "पैगंबर इब्राहिम (ए. ऐस्स.) दी दुआ-शैह्र ते उंʼदे ञ्याणें दी सुरक्षा आस्तै।", "तौहिद पर द्रिढ़ बने रहने आस्तै दुआ।"),
        "dua_drinking_milk" to DuaText("जिसलै दुग्ध पींदा आं", "हे अल्लाह, असां गी एह् आशीर्वाद देओ ते सानू एह्दे चा मता देओ।", "जिसलै दुग्ध पींदा ऐ।", "दूध भोजन ते पेय दौनें दे रूप च काफी ऐ।"),
        "dua_iftar_host" to DuaText("जिसलै दूसरो कन्नै तेजी कन्नै कम्म करना", "उपवास करने आह्ले लोक तुंʼदे कन्नै अपना व्रत तोड़ो, धार्मक लोक तुंʼदा भोजन खाएं ते स्वर्गदूत तुंʼदे आस्तै प्रार्थना करें।", "जिसलै कुसै दे घर च व्रत तोड़ो।", "मेजबान आस्तै पैगंबर जी दा सल्लल्लाह् सल्लल्लाहु अलैहि वसल्लम दुआ।"),
        "dua_seeing_first_fruit" to DuaText("पैह्ला फल दिक्खेआ", "हे अल्लाह, असां गी फल दे रूप च बरकत देओ, साडे शैह्र च बरकत देओ, ते साडे सा ते मड (माप) च बरकत देओ।", "मौसम दा पैह्ला फल दिक्खेआ।", "प्रावधान च ते अपने शैह्र च आशीर्वाद आस्तै दुआ।"),
        "dua_good_news" to DuaText("खुश करने आह्ली खबर", "सारी स्तुति अल्लाह आस्तै ऐ, जेह्दे कृपा कन्नै शैल चीजें गी पूरा कीता जंदा ऐ।", "अच्छी खबर मिलने पर (ते कृतज्ञता दा समर्पण करो)।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् किश नेहा दिक्खेआ जेह्ड़ा उʼनें गी पसंद हा।"),
        "dua_looking_mirror" to DuaText("शीशे च दिक्खेआ", "हे अल्लाह, जिʼयां तुस मेरे रूप गी चंगा बनाया ऐ, उʼयां गै मेरे चरित्र गी बी चंगा बनाओ।", "जब ऐना च दिक्खेआ जाई।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् दुआ बनाई (एह् शीशे दे जिकर दे बगैर बी स्थापत ऐ)।"),
        "dua_rabbana_taqabbal" to DuaText("कम्में दी स्वीकृति", "ऐ हमारे रब, असां शा एह् मंजूर करो, तुस सारे सुन्ने आह्ले, जानने आह्ले ओ। ते साʼदी तोह्फ मंजूर करो, तुस तोह्फ करने आह्ले, दयावान ओ।", "काबा दे निर्माण दे दुरान इब्राहिम ते इस्माइल (ए. ऐस्स.) ने आखेआ।", "हर इक भले कम्म दे परैंत्त स्वीकृति आस्तै दुआ।"),
        "dua_muawwidhat" to DuaText("त्रै कुल (मुआव्वित)", "(सूरह-उल-इखलास) आख जे ओह् इक-इक अल्लाह ऐ। अल्लाह, आत्मनिर्भर। ओह् ना पैदा होंदा ऐ ते ना पैदा होंदा ऐ। ते ओह्दे कन्नै कोई तुलना नेईं कीती जाई सकदी।\n\n(सूरह अल-तलाक) आखः में भ्यागा दे रब दी, उʼनें जेह्ड़ा किश बनाया ऐ ओह्दे बुराई थमां, अंधारे दी बुराई थमां जिसलै एह् ठीक होई जंदी ऐ, गांठें पर उड़ने आह्ले दी बुराई कोला ते ईर्ष्या करने आह्ले दी बुराई थमां जिसलै ओह् ईर्ष्या करदा ऐ, उंʼदी पनाह लैंदा आं।\n\n(सूरह-नास) आखः में जिन्नें ते इंसानें दे बिच्च थमां, मनुक्खें दे दिलां च फुसफुसाने आह्ले, पिट्ठियां करदे हुए फुसफुसाने आह्ले दी बुराई शा, मनुक्खें दे रब, मनुक्खें दे राजा, मनुक्खें दे रब च शरण मंगदा आं।", "त्रै सूरह हर भ्यागा ते सʼञै त्रै बारी, ते सोने शा पैह्लें, हथें च फूंकें ते उʼनें गी शरीर पर पोंछी देओ।", "उंʼदा त्रै बारी भ्यागा ते सʼञा पाठ करना हर चीज दे खलाफ काफी ऐ।"),
        "dua_sabr" to DuaText("धैर्य ते दृढ़ता आस्तै", "ऐ हमारे रब, हम पर धैर्य लाओ, हमारे पैर मजबूत करो ते इनकार करने आह्ले लोकें दे खलाफ साडी मदद करो।", "औकड़ें ते टकराव दे समें च।", "तालूत दी सैना दा दुआ।"),
        "dua_rabbana_innana_amanna" to DuaText("क्षमा ते अग्ग शा सुरक्षा", "हे हमारे प्रभु, असां विश्वास कीता ऐ, इस करियै असां गी साडे पाप क्षमा करी देओ ते सानू गी अग्ग दी सज़ाया शा बचाओ।", "इक कुरान दी दुआ।", "भगवान-भय दे गुणें च इक दुआ दा जिकर ऐ।"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("हमारे मामले च मार्गदर्शन (आशाब अल-कहफ)", "हे हमारे प्रभु, अपने आप थमां सानू पर दया करो ते साडे मामले च साडे आस्तै सही मार्गदर्शन त्यार करो।", "गुफा दे लोकें दा दुआ।", "फैसलें ते औखी परिस्थितियें च मार्गदर्शन।"),
        "dua_musa_faqir" to DuaText("प्रावधान आस्तै मूसा (ए. ऐस्स.) दा दुआ", "मेरे प्रभु, तुस मेरे पर जेह्ड़ा बी चंगा बख्शीदे ओ, उसी मिगी सच-च लोड़ ऐ।", "प्रावधान ते भलाई दी मंग करना-माद्यान च मूसा (ए. ऐस्स.) दी दुआ।", "इस दुआ दे परैंत्त, अल्लाह ने मूसा (अ. स.) गी इक घर, कम्म ते इक लाड़ी दित्ती।"),
        "dua_ayyub" to DuaText("अयूब (ए. ऐस्स.) दी दुआ बिमारी च", "(मेरे रब) ने मिगी नुकसान कीता ऐ, ते तुस दयावानें च सभनें शा मती दयावान ओ।", "रोग ते पीड़ च।", "अल्लाह ने अयूब (अ. स.) दी पीड़ गी दूर करी ओड़ेआ।"),
        "dua_husn_khatimah" to DuaText("मुसलमान दे रूपा च मरी जाओ (युसूफ ए. ऐस्स.)", "ऐ आसमानें ते धरती दे सिरजणहार, तुस इस दुनिया ते आख़िरत च मेरे रक्षक ओ। मिगी मुसलमान दे रूपा च मरने देओ ते सच्चें कन्नै मेरे कन्नै शामल होवो।", "इक अच्छे अंत आस्तै इक दुआ।", "पैगंबर यूसुफ (अ. स.) दी दुआ।"),
        "dua_shaitan_hamazat" to DuaText("शैतानें दे व्हिस्परें शा शरण", "हे मेरे प्रभु, में शैतानें दी फुसफुसियें शा तुंʼदे च शरण लैंदा आं, ते में तुंʼदे च शरण लैंदा आं, हे मेरे प्रभु, नेईं तां ओह् मेरे कोल आङन।", "शैतान दी फुसफुसियें शा बचो।", "शरण लैने दा इक कुरान दुआ।"),
        "dua_bad_character" to DuaText("बुरे चरित्र शा शरण", "हे अल्लाह, में तेरे च बुरे चरित्र, बुरे कर्में ते बुरी इच्छाएं शा पनाह लैंदा आं।", "बुरे चरित्र, कर्में ते इच्छाएं शा बचियां रहो।", "पैगंबर सल्लल्लाह् अलैहि वसल्लम थमां इक शरण दी दुआ।"),
        "dua_zawal_nimah" to DuaText("आशीर्वादें दे नुकसान शा शरण", "हे अल्लाह, में तुंʼदे आशीर्वाद दे नुकसान, तुंʼदे आसेआ दित्ती गेई भलाई दे बदलाऽ, तुंʼदी अचानक सज़ाया ते तुंʼदी सारी नाराज़गी शा तुंʼदे च शरण मंगदा आं।", "आशीर्वाद खोने ते अचानक आपदा शा शरण।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम दा इक दुआ।"),
        "dua_useless_knowledge" to DuaText("गैर-लाभकारी ज्ञान थमां शरण", "हे अल्लाह, में तुंʼदे च ऐसे ज्ञान थमां शरण मंगदा आं जेह्ड़ा फायदा नेईं करदा ऐ, इक ऐसे दिल शा जेह्ड़ा नेईं डरदा ऐ, इक आत्मा कोला जेह्ड़ा कदें बी संतुष्ट नेईं होंदा ऐ, ते इक दुआ कोला जेह्ड़ी जवाब नेईं दित्ती जंदी ऐ।", "बेकार ज्ञान ते अल्लाह दे डर दे बगैर दिल थमां शरण लो।", "पैगंबर सल्लल्लाह् अलैहि वसल्लम थमां इक शरण दी दुआ।"),
        "dua_beneficial_knowledge" to DuaText("लाभकारी ज्ञान ते हलाल रिज़क", "हे अल्लाह, में तुंʼदे शा लाभकारी ज्ञान, शुद्ध रोजी-रोटी ते मंजूर कीते गेदे कर्में आस्तै विनती करदा आं।", "फजर नमाज़ दे परैंत्त।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने फजर दी नमाज़ दे परैंत्त एह् आखेआ।"),
        "dua_leprosy_diseases" to DuaText("गंभीर रोगें शा शरण", "हे अल्लाह, में तुंʼदे च कोड, पागलपन, कुष्ठ रोग ते सभनें भैड़ियां बीमारियों शा पनाह लैंदा आं।", "गंभीर रोगें शा सुरक्षा।", "स्वास्थ दी रक्षा आस्तै सुन्नत दुआ।"),
        "dua_fear_people" to DuaText("दुश्मनें जां उत्पीड़कें दा डर", "हे अल्लाह, असीं तुसें गी उंʼदे पैह्लें स्थापत करदे आं ते उंʼदी बुराई शा तुंʼदे च शरण लैंदे आं।", "जिसलै कुसै लोकें जां कुसै व्यक्ति दे नुकसान दा डर होंदा ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् उसलै आखेआ जिसलै ओह् इक लोकें शा डरदे हे।"),
        "dua_shirk_protection" to DuaText("छिपी दी शिर्क शा सुरक्षा", "हे अल्लाह, में जान-बूझियै तुंʼदे कन्नै कुसै बी चीज गी सांठत करने शा तुंʼदे शा शरण लैंदा आं, ते में अपने अनजाने दे कम्में आस्तै तुंʼदी माफी मंगदा आं।", "दिखाना ते छिपी दी शिर्क शा सुरक्खत रेह्।", "छिपी दी शिर्क इक कीड़ी दे रेंगने दी तुलना च मती छिपी दी होंदी ऐ।"),
        "dua_rain" to DuaText("जिसलै बरखा होंदी ऐ", "ऐ अल्लाह, इक फायदेमंद बरखा (भेजो)।", "जिसलै बरखा होआ दी ऐ।", "बरखा इक नेहा समां ऐ जिसलै दुआएं गी मंजूर कीता जंदा ऐ।"),
        "dua_after_rain" to DuaText("बरखा दे परैंत्त", "अल्लाह दे बरकत ते उंʼदी दया कन्नै असां गी बरखा दित्ती गेई ऐ।", "बरखा दे परैंत्त।", "जेह्ड़ा एह् आखदा ऐ ओह् अल्लाह च विश्वास करदा ऐ।"),
        "dua_istisqa" to DuaText("बरखा दी मंग (इस्तिस्का)", "हे अल्लाह, असां गी त्र'ऊं बारी बरखा करा।", "जिसलै बरखा नेईं होंदी ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने शुक्करबार दे उपदेश च एह् दुआ कीती ते बरखा होई।"),
        "dua_heavy_rain" to DuaText("मती बरखा", "हे अल्लाह, (एह्) साडे आस्सै-पास्सै होन देओ, साडे पर नेईं।", "जिसलै मती बरखा होंदी ऐ।", "बादलें गी पैगंबर सल्लल्लाह् अलैहि वसल्लम दे दुआ दे राहें दूर कीता गेआ।"),
        "dua_wind" to DuaText("जिसलै हवा वगदी ऐ", "हे अल्लाह, में तुंʼदे शा एह्दे भले आस्तै, एह्दे अंदर दे भले आस्तै ते जेह्दे कन्नै एह् भेजेआ गेआ हा ओह्दे भले आस्तै मंगदा आं, ते में तुंʼदे च एह्दे बुरे, एह्दे अंदर दे बुरे ते ओह्दे कन्नै भेजे गेदे बुरे शा पनाह लैंदा आं।", "जिसलै तेज हवा जां तफान वगदा ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने तुफानें दे दुरान एह् दुआ बनाई ही।"),
        "dua_thunder" to DuaText("गर्जना दी अवाज", "महिमावान ऐ ओह् जिस्सी गर्जना ओह्दे स्तुति कन्नै महिमावान करदी ऐ, ते स्वर्गदूतां ओह्दे डर कन्नै।", "गर्जन सुनने पर-अब्दुल्ला इब्न अज़-जुबैर (रा.) दी प्रथा।", "सूरह अर-राद (13:13) थमां लैता गेआ ऐ।"),
    )
}
